const rawData = $json;

return {
  json: {
    attacker_ip: rawData.body?.result?.Source_Network_Address ?? rawData.Source_Network_Address ?? "unknown",
    username: rawData.body?.result?.Account_Name ?? "unknown",
    attempt_count: parseInt(rawData.body?.result?.count ?? 1),
    timestamp: new Date().toISOString(),
    source_host: rawData.body?.result?.ComputerName ?? "unknown"
  }
};

const vt = $('IP reputation check').item.json.data.attributes.last_analysis_stats.malicious || 0;
const abuse = $input.item.json.data.abuseConfidenceScore || 0;
const ip = $('data normalization').item.json.attacker_ip;

const score = Math.round(abuse * 0.6 + Math.min(vt / 10, 1) * 40);

return {
  json: {
    attacker_ip: ip,
    composite_risk_score: score,
    virustotal_detections: vt,
    abuseipdb_score: abuse
  }
};
